arguments.script:
UnityEngine.Debug.Log("SCENE="+UnityEngine.SceneManagement.SceneManager.GetActiveScene().path+" dirty="+UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty);
var p=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>("Assets/Prefabs/Character.prefab");
foreach(var j in p.GetComponentsInChildren<UnityEngine.Joint2D>(true)){
 UnityEngine.Debug.Log(j.name+" "+j.GetType().Name+" anchor="+(j is UnityEngine.AnchoredJoint2D a?a.anchor.ToString():"")+" connected="+(j.connectedBody==null?"null":j.connectedBody.name));
 if(j is UnityEngine.SliderJoint2D s)UnityEngine.Debug.Log("slide angle="+s.angle+" limits="+s.limits.min+","+s.limits.max+" use="+s.useLimits+" translation="+s.jointTranslation);
 if(j is UnityEngine.HingeJoint2D h)UnityEngine.Debug.Log("hinge limits="+h.limits.min+","+h.limits.max+" use="+h.useLimits);
}
